@dataclass
class Libro:
    isbn: str
    titulo: str
    copias_disponibles: int

    def reservar_copia(self) -> None:
        if self.copias_disponibles > 0:
            self.copias_disponibles -= 1
        else:
            raise ValueError("No hay copias disponibles")

    def liberar_copia(self) -> None:
        self.copias_disponibles += 1

